import {terminusSymbols,straussProjectors,aetherellaFigures} from '../app/utils/bo6Launch.mjs'
const reddit=map=>`https://www.reddit.com/r/CODZombies/wiki/${map}/`
const illustrated=map=>`https://www.codzombiesguides.com/main-quests/black-ops-6/${map}/`
const img=(map,name,alt)=>({src:`/images/bo6-${map}/${map}-${name}.webp`,alt})
const l=(name,alt)=>img('liberty-falls',name,alt)
const t=(name,alt)=>img('terminus',name,alt)
const step=(id,text,quick,extra={})=>({id,text,quick,...extra})
const phase=(id,title,steps,extra={})=>({id,title,steps,tools:[],...extra})
const reviewNote='Original walkthrough cross-checked against community and illustrated guides on 2026-10-02. Use Standard mode for the full set of side quests. Screenshots are credited to COD Zombies Guides and the r/CODZombies community wiki; local source manifests record each image. This revision has not yet been verified in a complete in-game run.'
export const guides=[
{
 id:'bo6-liberty-falls',gameId:'bo6',name:'Liberty Falls',reviewed:'2026-10-02',image:'/images/bo6-liberty-falls/liberty-falls.webp',reviewNote,
 intro:'Build the Jet Gun, capture two special enemies for Panos and survive the church finale. This guide covers the solo or co-op main quest, all nine Aetherella figures, bowling, the bank vault and the map’s reward secrets. The guaranteed Jet Gun route keeps the quest independent of Mystery Box luck. Use Quick Parts during a run and Full Details for the photographed locations, recovery steps and optional routes.',
 sources:[reddit('liberty-falls'),illustrated('liberty-falls'),'https://www.callofduty.com/guides/blackops6/zombies/call-of-duty-guides-black-ops-6-round-based-zombies-liberty-falls','https://www.reddit.com/r/CODZombies/comments/1gty41z/','https://www.dexerto.com/call-of-duty/all-side-easter-eggs-liberty-falls-black-ops-6-zombies-2965267/','https://www.youtube.com/watch?v=3bw0iHU8kRw','https://www.reddit.com/r/CODZombies/comments/1gz2w8w/'],
 phases:[
  phase('setup','Open the town & prepare your route',[
   step('setup-open','Open the road from Pump & Pay through Riverside and Washington Avenue to the church, buying the marked debris as you climb. Purchase the church’s dimensional barrier to reach Pack-a-Punch; Liberty Falls has no separate power-switch task. Interact with the S.D.G. machine against the church’s right wall and wait for the white flash and Panos’s dialogue.','Open church → Pack-a-Punch → interact with the S.D.G. on the right wall.',{images:[l('sdg-generator','The church S.D.G. starts the quest and receives both charged canisters')]}),
   step('setup-kit','Upgrade one reliable damage weapon and keep the Jet Gun as your crowd-control tool. Jugger-Nog, armor plates, Quick Revive and a charged defensive Field Upgrade make the holding steps safer. Carry Decoys or Monkey Bombs for the valve. If using Pack-a-Punched explosive weapons, buy PhD Flopper before relying on them at close range.','Bring armor, an upgraded damage weapon and distractions for stationary objectives.',{note:'The main quest works solo or in co-op. GobbleGums are optional. Standard mode supports the full set of side activities; Directed mode changes round progression and disables many side eggs.'})
  ],{group:'Key Features'}),
  phase('jet-gun','Build the Thrustodyne M23 / Jet Gun',[
   step('jet-valve','Take the small water valve from the hose fitting outside Lily’s Flowerpot on Washington Avenue, beside the bloody storefront door near Speed Cola. In Fuller’s Liberty Lanes, melee the square panel on the wall to the right of the lanes. Install the valve and hold interact until the pressure bar fills, then pick up the gauge that drops onto the floor.','Flower-shop valve → Liberty Lanes wall panel → hold interact → collect pressure gauge.',{images:[l('water-valve','The flower-shop hose fitting holds the removable water valve'),l('water-valve-pipe','Melee this bowling-alley panel and install the valve')],note:'Zombies keep arriving during the pressure task. Release interact to defend yourself, but stay in the bowling alley and resume promptly; leaving the area drains progress and can reset the attempt. In co-op, assign one turner and one guard. Solo, alternate short holds with a Decoy or Aether Shroud.'}),
   step('jet-brake','Spend time killing zombies in the Cemetery until the named Groundskeeper appears in overalls. Kill him before he leaves, collect his Toolshed Key and unlock the shed in the Groundskeeper’s Yard below the Cemetery. Take the handbrake from the table inside.','Kill Cemetery Groundskeeper → take key → unlock yard toolshed → collect handbrake.',{images:[l('toolshed-key','Collect the named Groundskeeper’s dropped key'),l('handbrake','The handbrake waits on the opened toolshed’s table')],note:'Do not mistake an ordinary zombie for the named Groundskeeper. If he escapes, keep playing and check the Cemetery again on later rounds.'}),
   step('jet-wire','Open Radio House at Riverside using a Mangler cannon blast: stand in front of its shutter, bait an enemy Mangler’s shot and move aside, or fire your own Mangler Cannon/Mutant Injection cannon into it. Interact with the debris piles inside until the wires are exposed, then pick them up.','Mangler blast opens Radio House → search floor piles → collect electrical wires.',{images:[l('radio-house','Radio House shutter: ordinary gunfire does not replace the Mangler blast'),l('electrical-wires','Search the interior piles for these electrical wires')],note:'A hostile Mangler gives a no-salvage route once one spawns. Some piles release Vermin, so clear the room before searching the next one.'}),
   step('jet-build','Approach the closed upstairs Motor Lodge room to make the zombies burst through its door. Clear them and build the Jet Gun at the workbench using all three parts. Its primary suction collects quest objects and kills groups; let its charge recover between uses.','All three parts → upstairs Motor Lodge workbench → build Jet Gun.',{images:[l('jet-gun','Build the Jet Gun in the upstairs Motor Lodge room')],note:'A Jet Gun obtained from the Mystery Box also works for the quest. Do not discard your only one before collecting the LTG parts or any Aetherella figures you want.'})
  ],{group:'Main Quest'}),
  phase('ltg','Collect all three LTG parts',[
   step('ltg-parts','Use the Jet Gun’s suction on each floating component. In Olly’s Comics, aim into the broken ceiling. On Washington Avenue, climb onto the delivery truck and aim into the open upper window of Buzz’s Cuts. In the church, aim up beside Panos at the balcony after the S.D.G. introduction has finished.','Vacuum LTG parts: Comics ceiling / Buzz’s Cuts upper window / church balcony.',{images:[l('ltg-first-part','Olly’s Comics: aim into the damaged ceiling'),l('ltg-second-part','Buzz’s Cuts: use the truck for a clear upper-window sightline'),l('ltg-final-part','Church: the component floats beside the balcony and Panos')]}),
   step('ltg-build','Reach The Alamo, the Savings & Loan bank roof, using the available ascender/roof route. Craft the LTG at the rooftop workbench. Clear a return route from Riverside up Washington Avenue to the church before starting the captures.','Craft LTG on The Alamo bank roof; open your church return route.',{images:[l('ltg','The LTG workbench sits on The Alamo bank roof')]})
  ]),
  phase('first-capture','First capture — Riverside to Pump & Pay',[
   step('capture-place','Take the empty Aether Canister sticking out of the S.D.G. and carry it down to the Dark Aether Field Generator trap between Pump & Pay and the Motor Lodge. Drop it directly beside one of the trap’s small ground emitters. Carrying a canister prevents sprinting, so make this delivery before summoning the enemy.','Carry S.D.G. canister to the Pump & Pay trap; drop beside one ground emitter.',{images:[l('first-aether-canister','Take the canister protruding from the S.D.G.'),l('dropped-aether-canister','The canister must sit inside one emitter’s capture field')],note:'There is no socket for this placement: drop the canister on the ground. This guide does Riverside first; Cemetery first is also valid if you swap both portal and nearby trap together.'}),
   step('capture-defend','Place the LTG beneath the storm cloud at Riverside/East Main Street and activate it. Protect the portal for its countdown, concentrating fire on zombies running into the device. A successful defense releases a named purple HVT. Damage it until its purple glow and dialogue indicate it is ready to capture, then stop shooting and lead it to your canister.','Defend Riverside portal → weaken the named HVT → lure it to the canister.',{images:[l('portal-defense','Defend the LTG beneath the Riverside storm cloud')],note:'An LTG defense failure can be retried on a later round. Killing the HVT away from the capture field also requires another spawn; do not keep firing while it is still walking toward the trap.'}),
   step('capture-kill','Activate the Dark Aether Field Generator and kill the weakened HVT while it stands inside the same emitter’s purple field as your canister. Watch for the energy transfer into the canister. Pick up the charged canister only when ready to leave, then walk it directly back to the church S.D.G. before the 90-second delivery timer expires.','Kill HVT in active field beside canister → pick up charge → return to S.D.G. within 90 seconds.',{images:[l('energy-transfer','The HVT’s energy must flow into the nearby canister'),l('leaking-aether-cannister','A charged canister starts the return countdown when carried')],note:'A death in a different emitter’s field does not count, even if the trap is on. If no transfer occurs, or the delivery fails, reset the capture on a later round. Keep explosives and automatic damage effects away from the target while positioning it.'})
  ]),
  phase('strauss','Strauss Counter — calibrate three projectors',[
   step('strauss-read','After returning the first charged canister, take the Strauss Counter from the left side of the S.D.G.; it replaces your tactical equipment. Visit the three projectors below and hold the tactical button near each one to read its local energy. Set that projector’s lamp to the inverse reading: Red/High becomes Green, Green/Low becomes Red, and Yellow/Medium stays Yellow.','Read each projector with Counter; Red → Green, Green → Red, Yellow → Yellow.',{images:[l('strauss-counter','The Strauss Counter is collected from the S.D.G. after the first charge')],bullets:['Hilltop Stairs: on the grass above Liberty Lanes, near PhD Flopper.','Groundskeeper’s Yard: beside the handbrake toolshed.','Yummy Freeze rooftop: open the wooden debris on The Alamo, then drop onto the lower ice-cream-shop roof.'],note:'The lamp cycles Green → Yellow → Red with interactions. Read each location separately; do not copy a color from a guide screenshot or treat all three projectors as one shared reading.'}),
   step('strauss-canister','When the three settings are correct, wait for their beams to converge on the device at Pump & Pay. Take its newly released second canister. Retrieve the LTG from the completed Riverside portal before heading back uphill.','Three beams meet at Pump & Pay → collect second canister → retrieve Riverside LTG.')
  ],{tools:['bo6-liberty-strauss']}),
  phase('second-capture','Second capture — Cemetery to Hill Street',[
   step('capture-two','Drop the second canister beside a ground emitter at the Hill Street Dark Aether Field Generator. Install the recovered LTG beneath the Cemetery storm cloud, defend the portal, and weaken the next named HVT. Lead it down to your chosen emitter, activate the trap and kill it inside that emitter’s field.','Hill Street canister → Cemetery LTG defense → weaken, lure and capture the second HVT.',{images:[l('second-portal-defense','The second portal site lies under the Cemetery storm cloud')]}),
   step('capture-return','After confirming the transfer, pick up the canister and return it to the S.D.G. within the delivery countdown. The machine is now ready to offer the final encounter. Resupply before accepting it; bringing the canister back does not require you to start the fight immediately.','Return charged canister before timeout; resupply before the church finale.',{note:'If you chose Cemetery first, perform this second capture at Riverside with the Pump & Pay trap instead. Each portal is used once successfully; keep the capture site and its nearest trap paired.'})
  ]),
  phase('finale','Church finale — three waves',[
   step('finale-ready','Upgrade your damage weapon, fill armor and ammo, replace tactical equipment after the Strauss step, and carry a self-revive where available. A defensive Field Upgrade and Mutant Injection are useful emergency options. Have every player accept the S.D.G. encounter when ready; the church becomes a closed arena.','Restock armor, ammo and equipment → all players accept the S.D.G. encounter.',{note:'Avoid starting with an empty Jet Gun meter. Keep an escape lane around the pews rather than grouping every player in one corner. Optional Aetherella can help, but collecting the ninth figure starts its effect immediately and is not a quest requirement.'}),
   step('finale-waves','Keep moving and clear the first wave of zombies and Manglers, claiming the Max Armor when needed. The second stage adds a named HVT Mangler: remove its arm cannon/armor and focus its exposed head while controlling ordinary zombies. Collect the resulting Max Ammo before pushing the last stage.','Wave 1 → Max Armor. Wave 2 → HVT Mangler → Max Ammo.',{images:[l('phase-2','The named Mangler is the second stage’s priority target')]}),
   step('finale-finish','The last stage brings an HVT Abomination alongside the horde. Shoot its glowing open mouths during attacks, keep out of its beam and charge lanes, and use the Jet Gun or support item to create room. When the final HVT dies, the scripted blast downs the team and triggers the ending. That forced down is the successful quest sequence.','Final wave → kill HVT Abomination → scripted down → ending.',{images:[l('phase-3','Use the Abomination’s exposed glowing mouths while maintaining space')],note:'There is no speed requirement for this encounter. Survival and controlled damage matter more than standing still for a full magazine.'})
  ])
 ],
 sidePhases:[
  phase('aetherella','Aetherella — all nine figures',[
   step('aetherella-route','Vacuum nine small figures with the Jet Gun’s primary fire. Four are inside Olly’s Comics; the other five are at the church window, Hill Street air conditioner, Liberty Lanes sign, Fast Forward roof and Motor Lodge sign. The photo checklist below gives each sightline and saves your progress.','Jet Gun suction → all nine figures → temporary Aetherella transformation.',{note:'The ninth pickup transforms you immediately and unlocks World Domination. Plan the last pickup for a crowded round or before an objective. The helper counts your confirmations; it cannot detect pickups from the game.'})
  ],{group:'Side Quests',tools:['bo6-liberty-aetherella']}),
  phase('vault','Savings & Loan vault — three notes in order',[
   step('vault-notes','Record three two-digit sticky-note values in this order: Savings & Loan reception desk; under the counter inside Olly’s Comics; the Liberty Lanes snack counter under the ice bucket, which you must shoot away. Enter those values at the bank vault door in the same order.','Vault order: bank desk → Comics counter → bowling snack counter.',{note:'Preserve leading zeros. The values change each match. The vault allows a limited number of wrong attempts per round, so read all three before experimenting.'}),
   step('vault-loot','Take Loot Keys dropped by special and elite enemies into the opened vault and spend them on the locked deposit boxes. Higher-rarity keys improve the reward quality. Your time inside is limited; decide which boxes you will open before lingering over rewards.','Bring colored Loot Keys from special enemies; open deposit boxes during the timed visit.')
  ],{tools:['bo6-liberty-vault']}),
  phase('bowling','Mister Peeks bowling — shoes & repeat games',[
   step('bowling-shoes','Shoot five hidden pairs of bowling shoes through their zombie windows. Hitting the final pair transports the team to the bowling minigame, so prepare the group before firing that last shot.','Shoot five pairs: gas station / hardware store / Hill Street house / Cemetery tree / funeral home.',{bullets:['Pump & Pay: counter inside the gas-station shop below the spawn rooftop.','Frank’s Hardware at Riverside: shelf through the open shopfront across from Olly’s Comics.','Hill Street: under a chair inside the house window near the AK-74 wall-buy.','Cemetery: shoes hang from a tree beyond the rear fence near the Tier III armor wall-buy.','Benson Funeral Services: on the coffin through the window across from Liberty Lanes.']}),
   step('bowling-play','Collect a bowling ball from Mister Peeks and hold fire to charge your throw. Aim down the lanes through groups of moving zombies; a charged ball can hit several in one pass. Keep collecting and throwing until the timer ends, then open the trophy for your reward. A score of at least 300 awards the bowling challenge reward.','Charge bowling throws through groups; collect the trophy after the timer.',{note:'For another game, wait at least five rounds and shoot the new shoes in the toilet through the zombie window beside the Liberty Lanes pool table. The initial five-shoe hunt is not repeated. Bowling supports three games in a match; the third also triggers the hidden song Echo.'})
  ]),
  phase('free-perk','Free Deadshot, Aether Tool & quick loot',[
   step('deadshot','At the back of the Cemetery, look beyond the boundary at five cans on a fence. With an accurate bullet weapon, hit all five without missing and within the short challenge window to receive Deadshot Daiquiri. A scoped, non-explosive weapon makes the small targets easier to distinguish.','Cemetery fence: shoot all five cans quickly without missing → free Deadshot.',{note:'A miss or timeout knocks the cans away. Advance a round and try again; do not use an explosive Pack-a-Punch conversion that makes exact hits unclear.'}),
   step('raining','Throw an explosive at the zombie/Mangler head mounted high on the front of the church. Falling zombies drop loot when they hit the ground. For a useful early weapon upgrade, wait until round 10 before triggering it to obtain the Rare Aether Tool reward.','Round 10+: explode the church-front head → collect falling-zombie loot and Rare Aether Tool.'),
   step('vending','Crouch and melee the retrieval opening of the vending machine beside the Motor Lodge stairs once each round for a small random reward. Melee Macchiato breaks it permanently and produces a final burst of loot, so leave that finish until you no longer want the repeatable attempts. Shoot the Liberty Lanes pool balls for a separate small Essence pickup.','Vending-machine opening: one crouched melee per round. Pool balls: shoot for Essence.',{note:'A rare weapon is possible from the vending machine, not guaranteed. Avoid promising a Ray Gun from any individual hit.'}),
   step('peeks-car','Check the intact black-and-yellow cars at Hilltop outside the church, beside the Groundskeeper’s Yard and outside Olly’s Comics. Find the one with Mister Peeks sitting inside, then hit it with a Mangler cannon blast. The trunk releases a random weapon. Recheck the remaining cars after five rounds.','Find Peeks inside an intact car → Mangler blast → trunk weapon; recheck after five rounds.',{note:'Blowing up a car before the toy appears wastes that car’s reward opportunity.'})
  ]),
  phase('music','Songs, dancing zombies & blood-pool rewards',[
   step('song','Hold interact on three Mister Peeks headphones to play Destroy Something Beautiful. Look on the ground in the Motor Lodge alley, on a church pew, and under the bench along the Washington Avenue fence. Listen for each pickup’s confirmation sound.','Song headphones: motel alley / church pew / Washington Avenue bench.'),
   step('rave','At Riverside, spend 50 Essence on each of the two viewfinders and aim each one at the dancing zombie on the distant cliff. Keep it centered long enough for the cue; after both are registered, the local zombies gather for a bus rave. If it does not activate, try both viewfinders again on a later round.','Use both Riverside viewfinders to watch the distant dancing zombie → bus rave.'),
   step('blood-pool','After a Vermin round, throw three Semtex into the fenced blood-filled swimming pool outside Liberty Lanes. The emerging red orb releases equipment, salvage and enemies. Repeat after later Vermin rounds; the third activation also awards a Fire Sale.','After Vermin rounds: three Semtex into fenced blood pool. Third activation adds Fire Sale.'),
   step('gravedigger','Use a Chopper Gunner to destroy the wooden barrel outside the map beside the Washington Avenue rooftops. Collect the shovel that falls near its base, then interact with dirt at Cemetery graves to dig up rewards or enemies. This costs a valuable support item, so do it as an optional loot hunt after securing your main-quest loadout.','Chopper Gunner destroys rooftop-side barrel → collect shovel → dig Cemetery graves.',{note:'Use the linked community screenshot for the barrel’s exact sightline before spending the Chopper Gunner.',links:[{href:'https://www.reddit.com/r/CODZombies/wiki/liberty-falls/#wiki_gravedigger',label:'Gravedigger barrel reference'}]})
  ]),
  phase('powerups','Hidden free power-ups — save them for useful moments',[
   step('powerups-list','Shoot a hidden miniature power-up to make its full-size pickup appear near you. Most are a one-time resource in that match, so leave Max Ammo and Full Power available for a defense rather than collecting them automatically.', 'Shoot the miniature; collect the power-up near your position.',{bullets:['Max Ammo: on the bridge beyond Pump & Pay.','Insta-Kill: on top of the church, visible from the Cemetery.','Bonus Points: upper window ledge across/outside Olly’s Comics.','Nuke: the Savings & Loan ceiling chandelier; an explosive inside or a shot through the roof opening can reach it.','Full Power: underneath the wrecked vehicle on West Main Street.','Max Armor: on a metal serving tray behind the Washington Avenue diner barrier.','Double Points: on the eastern water tower; use a scoped sightline from town.']})
  ]),
  phase('map-reference','Map reference — perks, upgrades & travel',[
   step('map-perks','The town is a loop with two climbs to the church. Riverside/Washington Avenue is useful for LTG parts; West Main Street/Liberty Lanes gives the valve task and PhD route. Use the bank ascenders and roof ziplines to cross quickly when not carrying canisters.','Riverside for LTG parts; Liberty Lanes for valve; bank roof for LTG workbench and travel.',{bullets:['Jugger-Nog: Savings & Loan. Quick Revive: Olly’s Comics. Stamin-Up: Liberty Lanes.','Speed Cola: Washington Avenue. PhD Flopper: Hilltop Stairs. Melee Macchiato: outside the church.','Der Wunderfizz: The Alamo bank roof from round 25; use it for perks without a local machine.','Arsenals at Riverside and the Cemetery handle weapon rarity and ammo mods. Pack-a-Punch is inside the church. Armor wall-buys include Olly’s Comics/West Main Street (Tier II) and Cemetery (Tier III).']})
  ])
 ]
},
{
 id:'bo6-terminus',gameId:'bo6',name:'Terminus',reviewed:'2026-10-02',image:'/images/bo6-terminus/terminus.webp',reviewNote,
 intro:'Restore the prison’s power, decode the Research Office, confront Nathan and stop Patient 13. This solo/co-op route includes a visual Beamsmasher solver, every network repair search, the timed hack-to-bomb transition, and the major island side quests. Use a boat for island work, read the current match’s clues, and finish your survival setup before starting timed objectives.',
 sources:[reddit('terminus'),illustrated('terminus'),'https://www.callofduty.com/guides/blackops6/zombies/call-of-duty-guides-black-ops-6-round-based-zombies-terminus','https://steamcommunity.com/sharedfiles/filedetails/?id=3362284904','https://www.codzombiesguides.com/side-quests/black-ops-6/terminus/whack-a-crab/','https://www.pcgamesn.com/call-of-duty-black-ops-6/terminus-boat-race','https://gameranx.com/features/id/516358/article/black-ops-6-zombies-how-to-get-all-free-power-ups-on-terminus/'],
 phases:[
  phase('power','Three AMP defenses & Pack-a-Punch',[
   step('power-amps','Follow the objective markers from the Holding Cells to three Aetherium Maturation Pods: Guard Station, Living Quarters and Bio Lab. Pay to start each generator and defend it from the purple-eyed zombies attacking it until its power-up finishes. The route opens the prison’s utilities and lower laboratory.','Defend AMPs in Guard Station → Living Quarters → Bio Lab.',{note:'Prioritize enemies targeting the generator. If its defense fails, clear the area and restart the machine when available. Progress on the other completed generators is retained.'}),
   step('power-pap','After the Bio Lab AMP is active, dive beneath the central platform and interact with the submerged lift control. Ride the raised platform to Pack-a-Punch. Use the Arsenal for Dead Wire on a conventional bullet weapon; that ammo mod is needed to open the Beamsmasher laboratory.','Raise submerged Bio Lab lift → Pack-a-Punch → equip Dead Wire for the free Beamsmasher.',{note:'A Beamsmasher from the Mystery Box satisfies the main quest requirement and skips its construction chain. The guaranteed build below avoids relying on box luck.'})
  ],{group:'Key Features'}),
  phase('beamsmasher','Open the Research Office & collect the EMF Fob',[
   step('beam-boxes','Ride the Pack-a-Punch lift upward with a Dead Wire weapon. Facing away from Pack-a-Punch, shoot the electrical box through the broken window partway up, then the box on the adjacent wall to the left, then the box behind Pack-a-Punch at the upper landing. Follow the current to Living Quarters and shoot its interior box, then the exterior box in Rec Yard beside the locked Research Office.','Dead Wire: lift window box → left wall → upper landing → Living Quarters → Rec Yard.',{images:[t('first-power-box','First electrical box: through the window opposite Pack-a-Punch'),t('second-power-box','Second box: turn toward the adjacent wall as the lift rises'),t('final-power-box','Third box: behind Pack-a-Punch at the upper landing'),t('living-quarters-power-box','Fourth box: inside Living Quarters'),t('research-office-power-box','Fifth box: outside the Research Office')],note:'Shoot the box receiving the current before moving onward. Missing a shot from the lift is recoverable; ride again or use the Bio Lab platform sightline. This is not a single timed five-shot challenge.'}),
   step('beam-fob','Enter the Research Office and kill the zombie pinned beneath debris. Take its EMF Fob. At Sea Tower, open the briefcase on the table beside Elemental Pop and collect the Multiphasic Resonator. Clear the Vermin that appear, then place the Resonator on the Research Office terminal.','Research Office pinned zombie → EMF Fob → Sea Tower case → Resonator onto lab terminal.',{images:[t('emf-fob','Collect the EMF Fob from the pinned zombie'),t('multiphasic-resonator','Sea Tower briefcase containing the Multiphasic Resonator'),t('research-office-terminal','Place the Resonator on the Research Office terminal')]})
  ],{group:'Main Quest'}),
  phase('lab-code','Laptop symbols → three terminal entries',[
   step('lab-laptops','Activate all three laptops: X at the Docks below Sea Tower, Y in Storage outside the Interrogation Rooms, and Z outside Communications beside the railing. Return to the Research Office and interact with its terminal so the three symbol notes appear. Match each letter’s actual symbol using the helper.','Activate Docks, Storage and Communications laptops; return to terminal for X/Y/Z notes.',{images:[t('final-laptop','X: the Docks laptop below Sea Tower'),t('second-laptop','Y: the Storage Area laptop'),t('first-laptop','Z: the Communications laptop')]}),
   step('lab-calculate','Each symbol has a fixed value read from the whiteboard: 0, 10, 11, 20, 21 or 22. Calculate the three entries in order: 2X + 11; (2Z + Y) − 5; and |(Y + Z) − X|. The last expression is absolute value, so its sign is removed if negative. Enter all three results into the terminal and confirm.','Enter 2X+11 → 2Z+Y−5 → absolute value of Y+Z−X.',{note:'Do not use another match’s code. Peck can sell the answer for 5,000 Essence, but the visual helper solves the same clues without the purchase. Only the final formula has absolute-value bars.'}),
   step('lab-wait','Let the locating sequence complete as rounds advance, then return when the terminal announces a target and shows an island map. Pick the Multiphasic Resonator back up before leaving. Travel by boat to Castle Rock Island on the eastern side of the sea.','Wait for scan completion → retrieve Resonator → boat to Castle Rock Island.',{note:'The current illustrated route places scan completion no earlier than round 9. Trust the terminal’s completion message rather than leaving after an assumed fixed delay.'})
  ],{tools:['bo6-terminus-lab']}),
  phase('island-orbs','Three island orbs & AMP Munition',[
   step('island-blue','Interact with the blue orb on Castle Rock Island to place the Resonator and begin. Wait for the orb to strike a zombie and make it glow blue. Kill that marked zombie, interact with its small dropped energy ball, and walk the ball into the large orb. Repeat until the orb changes color and departs.','Castle Rock: kill orb-marked blue zombies → carry their energy into the large orb.',{images:[t('blue-orb','Castle Rock’s blue orb marks the zombies that supply its energy')],note:'Ordinary kills do not replace the dropped-ball deliveries. Avoid killing every zombie before the orb can mark one. Clear nearby threats before picking up a ball because carrying it limits your actions.'}),
   step('island-repeat','Retrieve the Resonator from the ground where the orb was hovering. Follow it to Crab Island for the green stage, then retrieve it again and continue to Temple Island for the purple stage. Deliver matching energy balls at each island. After the purple stage, collect the AMP Munition and build the DRI-11 Beamsmasher at the Research Office workbench.','Pick up Resonator between stages: Castle Rock blue → Crab green → Temple purple → AMP Munition → craft.',{images:[t('green-orb','Crab Island hosts the green stage'),t('amp-munition','Collect the AMP Munition after the final orb stage')],note:'If the next orb will not start, check the previous island for your Resonator. Its pickup is easy to miss when chasing the flying orb.'})
  ]),
  phase('hard-drive','Damaged Tentacle Trap & Nathan’s code',[
   step('hard-drive-trap','Inspect the Tentacle Traps at Living Quarters, Holding Cells and both Bio Lab entrances. The correct vent is damaged and has a Project Janus card beneath it. Activate that trap, fire the Beamsmasher’s damaging beam into its tentacles and collect the dropped Hard Drive. Deliver it to the slot below Peck’s Guard Station window.','Find damaged Tentacle Trap → activate and beam it → Hard Drive → Peck.',{images:[t('third-trap','A broken vent and particles identify the target trap; this example is a Bio Lab entrance'),t('hard-drive','Take the dropped Hard Drive after shooting the active trap')],note:'There are four possible trap positions; older summaries sometimes count only three. Crouch or slide beneath an active trap instead of walking upright through its grasp.'}),
   step('nathan-code','Interact with the central Bio Lab chamber’s keypad/window to reveal Nathan. Record the three digits in fixed order: the hour on the Interrogation Rooms clock; the playing card’s number on the Mess Hall corkboard; and the Days Since Last Injury number in Engineering. Enter the resulting code at the chamber.','Nathan code: clock hour → Mess Hall playing card → Engineering injury sign.',{images:[t('first-digit','First digit: the short hour hand, read through the Interrogation Rooms barrier'),t('second-digit','Second digit: the Mess Hall corkboard playing card'),t('final-digit','Third digit: the Engineering safety sign')],note:'For a hand between 7 and 8, use 7. Ignore the minute hand. These digits are separate from the three Beamsmasher equation results.'})
  ],{tools:['bo6-terminus-nathan']}),
  phase('nathan','Defeat Nathan & recover the keycard',[
   step('nathan-fight','Restock before turning the chamber’s relief valves. In co-op, every player must hold a valve together. Nathan emerges as a powerful Amalgam; keep moving around the Bio Lab walkways, damage his exposed heads and use the Beamsmasher’s slowing/weakening alternate fire to help your damage weapon. Avoid being grabbed or pushed into a congested stairwell.','All players hold valves → defeat Nathan while circling the lab.',{images:[t('relief-valve','Every player holds one of the relief valves to release Nathan')],note:'Bring an upgraded weapon and armor before the trigger. A defensive Field Upgrade buys space if the arena becomes crowded. Dead Wire is useful against the Amalgam family.'}),
   step('nathan-keycard','After the cutscene, dive below the central chamber and collect the Project Janus Keycard from the Bio Lab floor. Visit Communications and interact with the computer showing green text to discover the network error. Both the keycard and this computer interaction are needed before continuing to repairs.','Collect underwater Janus Keycard → Communications green-text computer.',{images:[t('janus-keycard','Find the Project Janus Keycard underwater beneath Nathan’s chamber'),t('network-connection-error','Use this Communications computer to request network repairs')]})
  ]),
  phase('network','Shipwreck lockdown & two Node Connectors',[
   step('network-lockdown','Take a boat to the Shipwreck and climb the ladder under its broken hull into the keycard-locked room. Picking up a Node Connector from the worktable starts a confined lockdown. Survive the zombies and Vermin until the hatch reopens; take the connector with you.','Shipwreck underside ladder → collect connector → survive lockdown.',{images:[t('node-connectors','Two Node Connectors on the Shipwreck room’s worktable')],note:'Bring ammunition and crowd control before picking it up. Solo, install one connector and return for the other. In co-op, two players can each carry one.'}),
   step('network-install','Check three pipe endpoints and repair the two that are actually missing a connector: Docks beneath Sea Tower, Sea Caves opposite Speed Cola, and the Crab Island shore facing the Shipwreck. Insert a carried connector into each visible gap. Return to Peck and take the Hacking Device after both repairs are acknowledged.','Repair the two empty endpoints among Docks / Sea Caves / Crab Island → collect Hacking Device.',{images:[t('first-connection-line','Docks endpoint below Sea Tower'),t('second-connection-line','Sea Caves endpoint opposite Speed Cola'),t('final-connection-line','Crab Island endpoint facing Shipwreck')],note:'Two of the three need repairs each match. A pipe already joined is not another puzzle or a failed interaction; move to the next location.'})
  ]),
  phase('hacking','Prepare once, then hack buoys & defuse bombs',[
   step('hack-prepare','Before touching a buoy, fill ammo and armor, secure a usable boat and bring at least two distractions plus a charged defensive Field Upgrade. Learn the direct route from the sea to the Bio Lab. The buoy task flows into a lethal bomb timer, so this is the time to shop and regroup.','Resupply and stage a boat before the first buoy; bomb timer follows immediately.'),
   step('hack-buoys','Find the three buoys surrounded by Parasites in the northern, southeastern and southwestern sea. Approach each by boat and hold interact with the Hacking Device. The first completed hack starts a two-minute window for the other two; drive a continuous circuit and let a teammate clear the Parasites while you hack.','Hack all three sea buoys within the two-minute sequence.',{images:[t('buoy','A buoy surrounded by Parasites is a hacking target')],note:'If the buoy timer expires, repeat the hack sequence. Do not confuse this retryable timer with the next bomb timer, which ends the match if it expires.'}),
   step('hack-bombs','Immediately return to the Bio Lab after the third hack. Three recessed bomb panels open on the Melee Macchiato side: two on the lower walkway and one on the upper level. Hold interact at each until its defuse completes before the shared five-minute timer reaches zero. Use Decoys/Monkey Bombs or Aether Shroud to cover the long holds.','Bio Lab: defuse two lower bombs and one upper bomb before the five-minute match-ending timer.',{images:[t('bomb','Hold interact at each opened bomb panel until it finishes')],note:'Zombies continue spawning. Extra specials arrive as defuses complete. In co-op, assign defenders and allow the defuser to finish an uninterrupted hold; the reported co-op behavior resets interrupted progress. Solo progress can be resumed. The timer does not stop while you buy equipment.'})
  ]),
  phase('patient-13','Patient 13 — weak points, cover & three phases',[
   step('patient-ready','After all three bombs are safe, take time to finish preparations. Aim for a high-rarity, heavily Pack-a-Punched damage weapon, Tier III armor, survival perks, spare plates and a self-revive. Save enough Essence for arena ammo. Carry a strong support item if you have one. Enter the now-open Bio Lab door near Melee Macchiato only when every player is ready.','Bombs safe → finish upgrades and ammo budget → all players accept Patient 13 entrance.',{images:[t('boss-entrance','The Bio Lab door near Melee Macchiato starts the final encounter')],note:'Entry is a commitment: the team cannot return to the map to buy missing equipment. Expensive wonder-weapon ammunition is a reason to keep an ordinary damage weapon as well.'}),
   step('patient-one','In the first phase, shoot the glowing red shoulder growths whenever they open. Stop spending ammo on armored body areas. Move sideways when Patient 13 lifts its arms for a slam and keep clear of the follow-up sweep. Kill dangerous specials as they arrive instead of letting them accumulate behind you.','Phase 1: red shoulders; dodge slams/sweeps and clear specials.',{images:[t('phase-1','Patient 13’s glowing shoulder growths are the first phase’s damage windows')]}),
   step('patient-two','When the boss submerges, clear the attacking zombies and projectile tentacles, move off acidic puddles and replenish at the incoming Max Ammo. On its return, damage the glowing arm targets; when it glows red and exposes its mouth, shift fire into the mouth. The rest of its body remains heavily armored.','Intermission: clear threats and refill. Phase 2: arm weak points, then glowing mouth.',{images:[t('phase-2','The mouth becomes the damage target during Patient 13’s red state')]}),
   step('patient-three','The final phase adds a blue electrical blast. As the boss charges and the screen takes on a blue aura, break line of sight behind solid arena cover or jump into the water and use a ladder afterward. Do not continue firing in the open. Watch for the tongue grab in front of it; keep away from that lane and help a grabbed player by shooting the active weak point.','Phase 3: blue charge means hide or dive; avoid tongue; shoot glowing eyes/active weak points.',{images:[t('wipe-mechanic','Blue charge: immediately break the boss’s line of sight'),t('phase-3','Final phase: the glowing eyes and returning exposed targets allow damage')],note:'Keep your route to cover or a ladder clear. Side tentacles restrict the platform, so water can reconnect the separated sides. Use emergency support from a sheltered corner; continue moving and damaging exposed targets until the ending triggers.'})
  ])
 ],
 sidePhases:[
  phase('talisman','Captain’s treasure & Cursed Talisman',[
   step('pirate-watch','With Melee Macchiato, punch the cracked stone barrier in Sea Caves near Speed Cola to expose the captain’s skeleton and map. Interact with him, inspect the map’s X and dive at that indicated location for his watch. Bring the watch back to reveal three further marked sites.','Melee Macchiato cave wall → captain → marked underwater watch → return it.'),
   step('pirate-coins','Bring fire equipment to the skeletons at Castle Rock Island, Temple Island and the Shipwreck. Burn each skeleton with a Molotov, defeat the summoned named Mangler, collect its cursed coin and return it to the captain before collecting the next coin. Three deliveries reward weapons and reveal the final destination.','Burn three marked skeletons → defeat HVT Manglers → return one coin at a time.',{bullets:['Castle Rock: buried in sand right of the GobbleGum machine, beside an electrical cable.','Temple Island: on the stone steps left of the ammo cache.','Shipwreck: leaning against the bottom of the mast.'],note:'Carry coins directly back; their curse impairs normal recovery. The skeleton sites are fixed, while the first watch clue comes from your match’s map.'}),
   step('pirate-finish','Go to Crab Island, the final marked location, and progress about three rounds until the storm forms above it. A glowing treasure chest appears; open it and take the Cursed Talisman for Treasure Hunter. It doubles Essence earnings but also deducts points when you are hit, with a short cooldown between deductions.','Progress about three rounds → Crab Island storm chest → take Cursed Talisman.',{note:'This reward is optional for the main quest. Read its risk before collecting it, especially if you are saving points for ammo. Return it to the chest if you want to stop carrying it.'})
  ],{group:'Side Quests'}),
  phase('stuffy','Mega Stuffy — six plush toys',[
   step('stuffy-find','Interact with six plush toys around the map, preferably while already visiting the islands for the Beamsmasher. Collect them gently rather than shooting them to retain the small collection rewards.','Collect six plushies → Living Quarters beds → assemble Mega Stuffy.',{bullets:['Control Center: unicorn inside the cracked-open locker beside Stamin-Up.','Sea Tower bridge: monkey behind the fence on the Engineering side of the bridge.','Bio Lab: teddy under the medical table near the crafting area.','Mining Tunnels: elephant in the corner near the GobbleGum machine.','Shipwreck: duck inside the open red rubbish container opposite the SVD wall-buy.','Crab Island: giraffe behind the light between the LR 7.62 wall-buy and crafting table; crouch if needed.']}),
   step('stuffy-build','Return to the Living Quarters bunks and interact with a collected plush on a bed. The toys combine into Mega Stuffy, a temporary flying companion that attacks enemies and can revive players. It cannot accompany you into the final boss arena; keep your armor and self-revive plan.','Interact with a plush on the Living Quarters beds to summon the companion.')
  ]),
  phase('free-perks','Three free-perk routes & the rebreather',[
   step('caged-perk','In Bio Lab, kill every caged zombie around the upper room during one round. On the next round, kill every Vermin that replaces them; on the following round, kill the caged Mangler(s) for a Random Perk drop. Complete each set fully before advancing.','Bio Lab cages: all zombies → next round all Vermin → next round Mangler → perk.',{note:'Leaving a living member of an activated set when the round changes can break this sequence for the match. Check the cages carefully rather than assuming one kill is sufficient.'}),
   step('spore-perk','Cruise around the offshore rock formations until you find one covered in yellow spores. Shoot every spore and listen for the completion sound. On a later round, find and clear another infected rock; repeat for a third rock on another round. Then clear the newly grown spores inside Sea Caves to earn a Random Perk and loot.','Clear three spore rocks on separate rounds → clear Sea Caves spores → perk.',{note:'Circle each rock in the boat to see the hidden faces. Parasites spawn when spores burst. Clearing a rock also temporarily helps with the sea tentacle threat.'}),
   step('sea-chests','Search the seabed for ten small caches outlined by yellow lights and open every cache for a Random Perk from the final one. Work along the shores and around the islands between quest trips. Opened caches already count; the chest hunt is separate from the captain’s final chest.','Open ten glowing underwater caches; the final cache awards a Random Perk.'),
   step('rebreather','In the Bio Lab water beneath the Pack-a-Punch lift, find the bubbling rock and break it with an explosive. Collect the exposed oxygen mask/rebreather to extend underwater time for its holder. Get this before a long cache or watch search.','Explode the bubbling rock under the Bio Lab lift → collect rebreather.',{note:'The community route reports a single pickup for the match, so agree who will do the underwater collecting in co-op. Extra breathing time is not unlimited oxygen.'})
  ]),
  phase('crab-race','Whack-a-Crab & toy-boat racing',[
   step('crabs','On Crab Island, knock the cage from the central rock with an explosive. Melee the crabs that appear beneath it to begin a timed batting minigame. Hit as many emerging crabs as possible for a perk reward. The other crab groups offer a rare weapon left of the Tier III armor buy, points opposite it, and salvage between the first group and the crafting table.','Explode central crab cage → melee each crab group → timed minigames and location-based rewards.',{note:'A perk can reward is not guaranteed to be one you are missing. Attempt the perk group before purchasing every perk.'}),
   step('races','Dive near the toy boats around the outer island shores and interact with the one whose light is blinking. The active toy starts a boat-race vote in co-op or the race directly in solo. Follow the checkpoint route, avoid obstacles and tentacles, then open Mister Peeks’s trophy for rewards based on your result.','Find a blinking underwater toy boat → race through checkpoints → claim trophy.',{bullets:['Castle Rock: pink boat off the eastern shoreline.','Crab Island: yellow boat by the southeastern shoreline beneath the overhanging tree.','Temple Island: blue boat by the northern/northwestern edge near the ruins.'],note:'An unlit toy is not the current start point. Check the other islands or a later round; repeatedly interacting with an inactive toy does not begin the event.'})
  ]),
  phase('fish','Cooking, Peck’s refund & the fish perk reward',[
   step('cook-fish','Explode a school of visible fish in the sea and collect a fish. Take the cooking oil from beside the Mess Hall stove and gather a special ingredient before interacting with the pan. Put the ingredients in, advance one round and return to eat the cooked fish for Culinary Delight.','Fish + Mess Hall oil + special ingredient → pan → next round eat.',{bullets:['Chili in Mess Hall: Napalm Burst.','White ingredient above the Living Quarters refrigerator (commonly called salt or a snowball): Cryofreeze.','Brain on the Bio Lab medical scale/table: Brain Rot.','Mushroom on the dirt outside Storage/Interrogation: Shadow Rift.','Battery on the Engineering worktable: Dead Wire.'],note:'Collect what you need before starting the pan. Return the next round; leaving it longer can burn the food. The ingredient bonus is temporary, not a permanent new ammo mod.'}),
   step('peck-fish','If you paid Peck 5,000 Essence for the lab code, cook a plain fish with oil and no special ingredient. Take the cooked fish instead of eating it and bring it to Peck’s window to request your refund.','Paid for the code? Cook plain fish + oil, take it to Peck for the refund.'),
   step('fish-perks','Use explosives on visible schools of fish around the Docks, Shipwreck, Crab Island and Bio Lab water as they respawn. Killing 50 fish across the match grants the free all-perks reward. Count individual fish, not 50 schools; one blast can kill several.','Explode 50 individual fish over the match → all-perks reward.',{note:'Each player must make their own 50 fish kills. Look for bubbles at the surface and check fish spots again on later rounds. This is a longer optional reward route; keep enough ammunition for the main quest.'})
  ]),
  phase('meteor','Meteor, music & small secrets',[
   step('meteor','With a Pack-a-Punched Dead Wire weapon, shoot the electrical lights atop the two radio towers visible outside Communications and above Engineering in quick succession. When both stay lit, advance the round and activate the Void Cannon at Gun Platform. Watch for the meteor strike on Castle Rock Island, then travel there to collect its scattered loot.','PaP + Dead Wire: charge both towers → next round Void Cannon → Castle Rock meteor loot.',{note:'A wonder weapon can be among the drops but is not guaranteed. If the towers go dark without a meteor, recharge them and repeat the sequence.'}),
   step('term-song','Hold interact on the Mister Peeks headphones in Engineering near the stairs, Mining Tunnels across from PhD Flopper, and the upper Bio Lab conference room. All three play Can You Hear Me (Come In).','Headphones: Engineering / Mining Tunnels / upper Bio Lab.'),
   step('basketball','From the Engineering side, shoot the basketball resting on the Living Quarters roof with a Pack-a-Punched bullet weapon so it falls into the Rec Yard hoop. A successful basket releases Essence. Shoot the Living Quarters pool-table balls for a separate small Essence reward.','PaP shot knocks rooftop basketball into Rec Yard hoop; pool balls give a separate pickup.'),
   step('sentinel','On Temple Island, aim the Beamsmasher’s slowing alternate fire at the Sentinel Artifact drawing right of the PU-21 wall-buy to return to Security Overlook. This is useful after island work when you already have the weapon. Eight uses also award Essence and salvage.','Beamsmasher alternate fire at Temple Island’s Sentinel drawing → return teleport.',{note:'This is optional travel, not the damaging beam used for the Hard Drive. Do not rely on the extra loot to fund a timed objective.'}),
   step('elevator','For the elevator horror scene, jump as the Holding Cells elevator doors close on a descent to Bio Lab. The sequence changes the lift’s appearance temporarily and is a novelty rather than an equipment reward.','Jump as the Holding Cells elevator closes for the optional scare sequence.')
  ]),
  phase('term-powerups','Seven hidden power-ups',[
   step('term-powerups-list','Shoot the small hidden model to spawn the matching power-up near your position. Keep the ammo, armor and Full Power pickups in reserve if you plan to use them during a difficult round.','Find and shoot the miniature; the usable pickup appears nearby.',{bullets:['Max Ammo: window of the watchtower above the Interrogation Rooms, viewed from Rec Yard.','Max Armor: bucket beside the torture chair behind the Interrogation Rooms barrier.','Double Points: behind boxes on the cabinet in the upper Bio Lab office/conference room.','Full Power: outer metal ledge/beam beneath the inaccessible Sea Tower; a boat gives the clearest angle.','Insta-Kill: high ledge on Temple Island’s ruined wall above a zombie opening.','Nuke: on the ground inside the eastern rock-spawn opening on Crab Island.','Bonus Points: high window of the Shipwreck bridge/control room; aim through the opening.']})
  ]),
  phase('term-reference','Map reference — perks, transport & upgrades',[
   step('term-services','The prison is linked vertically by the Holding Cells elevator, the Bio Lab lift and cliffside routes. Use the sea’s tactical rafts for all island steps and check the map before a long boat trip. Boat pickups/launch points are along the shore, including Docks; leave a boat facing your next destination when preparing the timed hacks.','Prison ↔ Bio Lab by lift; islands by raft; keep a route back to the laboratory.',{bullets:['Quick Revive: Interrogation Rooms. Jugger-Nog: Living Quarters. Stamin-Up: Control Center above Communications.','Elemental Pop: Sea Tower. Speed Cola: Sea Caves. Deadshot Daiquiri: Seaside Path. PhD Flopper: Mining Tunnels. Melee Macchiato: Bio Lab.','Der Wunderfizz: Shipwreck from round 25, providing the perk catalogue.','Arsenals include Mess Hall and Bio Lab for rarity and ammo mods. The Bio Lab Pack-a-Punch rides the central lift.','The Armory in Control Center uses Loot Keys from special/elite enemies for locker rewards; save higher-rarity keys for a timed visit when you need equipment.']})
  ])
 ]
}
]
// Keep side-quest photo groups together so their sightlines are easy to audit.
const sidePhotos={
 'vault-notes':[l('vault-first-code','Vault entry 1: note on the Savings & Loan reception desk'),l('vault-second-code','Vault entry 2: note beneath the Olly’s Comics counter'),l('vault-final-code','Vault entry 3: remove the ice bucket on the Liberty Lanes snack counter')],
 'bowling-shoes':[l('bowling-shoes-pump-and-pay','Bowling shoes: gas-station counter'),l('bowling-shoes-riverside','Bowling shoes: shelf in Frank’s Hardware'),l('bowling-shoes-hill-street','Bowling shoes: house window near the Hill Street AK-74'),l('bowling-shoes-cemetery','Bowling shoes: tree beyond the Cemetery fence'),l('bowling-shoes-west-main-street','Bowling shoes: coffin in Benson Funeral Services')],
 deadshot:[l('deadshot-ee','The five cans stand on the fence beyond the Cemetery boundary')],
 gravedigger:[l('gravedigging-barrel','Ping this barrel above the Washington Avenue rooftop Mystery Box before activating your support item')],
 song:[l('music-ee-church-headphones','Song headphones on a church pew'),l('music-ee-motor-lodge-alley-headphones','Song headphones on the ground in the motel alley'),l('music-ee-washington-ave-headphones','Song headphones under the Washington Avenue bench')],
 'pirate-watch':[t('cursed-talisman-wall','Melee Macchiato breaks this Sea Caves wall to expose the captain')],
 'pirate-coins':[t('cursed-talisman-first-skeleton','Castle Rock skeleton: sand by the cable and GobbleGum machine'),t('cursed-talisman-second-skeleton','Temple Island skeleton: stone steps by the ammo cache'),t('cursed-talisman-final-skeleton','Shipwreck skeleton: base of the mast')],
 'stuffy-find':[t('mega-stuffy-unicorn','Control Center unicorn: open locker beside Stamin-Up'),t('mega-stuffy-monkey','Sea Tower bridge monkey: beyond the fence'),t('mega-stuffy-elephant','Mining Tunnels elephant: hole by the GobbleGum machine'),t('mega-stuffy-bear','Bio Lab bear: laboratory furniture between armor and crafting table'),t('mega-stuffy-duck','Shipwreck duck: red rubbish container opposite the SVD'),t('mega-stuffy-giraffe','Crab Island giraffe: behind the light beside the crafting route')],
 rebreather:[t('underwater-crates-oxygen-tank','Break the bubbling rock under the Bio Lab lift to expose the oxygen tank')],
 crabs:[t('whack-a-crab-cage','Explode this cage on Crab Island’s central rock to begin the crab minigames')],
 races:[t('boat-race-locations','Three toy-boat search locations around the islands; interact with the blinking toy')],
 meteor:[t('meteor-crash-storage-tower','First meteor tower: shoot its light using a Pack-a-Punched Dead Wire weapon'),t('meteor-crash-engineering','Second meteor tower: charge it promptly after the first')],
 'term-song':[t('music-ee-engineering-headphones','Engineering headphones near the steps'),t('music-ee-mining-tunnels-headphones','Mining Tunnels headphones opposite PhD Flopper'),t('music-ee-bio-lab-headphones','Headphones in the upper Bio Lab conference room')]
}
for(const guide of guides) for(const p of guide.sidePhases) for(const s of p.steps) if(sidePhotos[s.id]) s.images=sidePhotos[s.id]
const liberty=guides.find(g=>g.id==='bo6-liberty-falls')
liberty.sidePhases.find(p=>p.id==='music').steps.push(step('church-candles','Equip Napalm Burst and shoot both candle groups beside Pack-a-Punch: one on its left, and one in the right-hand corner. Igniting both creates fire patches in the church that damage players as well as zombies. It can be activated again in later rounds.','Napalm Burst both candle groups beside Pack-a-Punch → temporary church fire trap.',{images:[l('candles-first-location','First candle group: left of Pack-a-Punch'),l('candles-second-location','Second candle group: corner right of Pack-a-Punch')],note:'This is optional. Keep clear of the flames and leave yourself a safe movement route if using it during the church finale.'}))
liberty.sidePhases.find(p=>p.id==='powerups').steps.push(step('liberty-fire-sale','After shooting all seven other hidden power-up models, find the Fire Sale model in the garbage bin left of PhD Flopper at Hilltop Stairs. Shoot it for the additional pickup. This is separate from the blood-pool Fire Sale.','All seven hidden models → bin left of PhD Flopper → hidden Fire Sale.',{images:[l('fire-sale','The final hidden Fire Sale appears in the bin beside PhD Flopper')]}))
const terminus=guides.find(g=>g.id==='bo6-terminus')
terminus.sidePhases.find(p=>p.id==='term-powerups').title='Hidden power-ups & the final Fire Sale'
terminus.sidePhases.find(p=>p.id==='term-powerups').steps.push(step('terminus-fire-sale','After shooting all seven other power-up models, look into the zombie opening at Security Overlook. Shoot the new Fire Sale model on the barrel inside to spawn its pickup.','All seven hidden models → Security Overlook spawn-window barrel → Fire Sale.',{images:[t('fire-sale','The final Fire Sale model appears on this Security Overlook barrel')]}))
for(const [guide,slugs] of [[liberty,['the-vault','mister-peeks-bowling','gravedigging','hidden-power-ups','candles-fire-trap']],[terminus,['cursed-talisman','mega-stuffy-pet','cooking-fish','perkaholic','hidden-power-ups-terminus','sentinel-artifact-rune']]]) for(const slug of slugs) guide.sources.push(`https://www.codzombiesguides.com/side-quests/black-ops-6/${guide.id.replace('bo6-','')}/${slug}/`)

const field=(id,label,options=null,extra={})=>({id,label,options,...extra})
const tool=(id,map,name,help,fields,extra={})=>({id,map,name,help,fields,version:1,kind:'recorder',...extra})
export const tools=[
 tool('bo6-terminus-lab','bo6-terminus','Beamsmasher visual lab solver','Match the three X/Y/Z notes to verified symbol images. The helper shows the three terminal entries and every calculation, including the final absolute value.', ['x','y','z'].map(key=>field(key,`${key.toUpperCase()} symbol`,terminusSymbols.map(s=>s.value))),{kind:'solver',custom:true,reference:illustrated('terminus')}),
 tool('bo6-liberty-strauss','bo6-liberty-falls','Strauss Counter & projector helper','Record the counter reading at each photographed projector. See the correct lamp color, then confirm the setting in game. Changing a reading clears its confirmation.',straussProjectors.flatMap(p=>[field(p.id,`${p.name}: counter reading`,['red','yellow','green']),field(`${p.id}-done`,`${p.name}: set in game`,null,{type:'check'})]),{kind:'solver',custom:true,reference:illustrated('liberty-falls')}),
 tool('bo6-liberty-aetherella','bo6-liberty-falls','Aetherella photo checklist','All nine Jet Gun sightlines, including the rooftop figures. Save each pickup and plan the final figure: collecting number nine transforms you immediately.',aetherellaFigures.map(p=>field(p.id,p.name,null,{type:'check'})),{kind:'tracker',custom:true,reference:reddit('liberty-falls')}),
 tool('bo6-liberty-vault','bo6-liberty-falls','Bank vault code recorder','Read each note in your match. Enter Bank → Comics → Bowling at the vault; keep both digits, including a leading zero.',[field('bank','1 · Savings & Loan reception desk',null,{pattern:'^\\d{2}$',maxLength:2,inputmode:'numeric'}),field('comics','2 · Under Olly’s Comics counter',null,{pattern:'^\\d{2}$',maxLength:2,inputmode:'numeric'}),field('bowling','3 · Bowling snack counter, under ice bucket',null,{pattern:'^\\d{2}$',maxLength:2,inputmode:'numeric'})],{evaluate:'ordered',reference:reddit('liberty-falls')}),
 tool('bo6-terminus-nathan','bo6-terminus','Nathan’s chamber code recorder','Read the short clock hand, then the playing card, then the Days Since Last Injury sign. These three digits are separate from the Beamsmasher equations.',[field('clock','1 · Interrogation clock hour',null,{pattern:'^\\d$',maxLength:1,inputmode:'numeric'}),field('card','2 · Mess Hall playing card',null,{pattern:'^\\d$',maxLength:1,inputmode:'numeric'}),field('injury','3 · Engineering injury sign',null,{pattern:'^\\d$',maxLength:1,inputmode:'numeric'})],{evaluate:'ordered',reference:illustrated('terminus')})
]
